const bar = document.querySelector('.hud-bar');
if (bar && 'ResizeObserver' in window) {
new ResizeObserver(() => {
document.documentElement.style.setProperty('--hud-h', `${Math.ceil(bar.getBoundingClientRect().height)}px`);
}).observe(bar);
}
for (const meter of document.querySelectorAll('.race__bars .bar')) {
const label = meter.querySelector('i');
const fill = meter.querySelector('b');
if (!label || !fill) continue;
const value = Number.parseFloat(fill.style.getPropertyValue('--seg'));
if (!Number.isFinite(value)) continue;
const text = document.createElement('span');
text.className = 'sr-only';
text.textContent = ` ${value} of 16`;
label.appendChild(text);
}
